const cfg = $('Load Config').first().json;
const tpl = $('Get Templates').all().map((i) => i.json).find((t) => t && t.slug === 'style_sheet');
if (!tpl || !tpl.body) throw new Error('no active style_sheet template in prompt_templates - profiling without per-image sheets');
const refs = $('List Library').all().map((i) => i.json);
const urls = $input.all().map((i) => cfg.sbUrl + '/storage/v1' + String(i.json.signedURL || '')).filter((u) => /token=/.test(u));
if (!urls.length) throw new Error('no signed library URLs');
if (urls.length !== refs.length) throw new Error('Could not sign ' + (refs.length - urls.length) + ' of ' + refs.length + ' library images - skipping per-image sheets');
// one studio note per image, in IMAGE 1..N order: kind / garment / best-example tags / outlier from client_references.meta, then the free-text note
const noteLine = (r, i) => { const m = (r.meta && typeof r.meta === 'object') ? r.meta : {}; return 'Image ' + (i + 1) + ': ' + (m.kind || 'design') + (m.garment ? ' on a ' + m.garment + ' garment' : '') + (Array.isArray(m.best_for) && m.best_for.length ? '; best example of ' + m.best_for.join(', ') : '') + (m.outlier ? '; OUTLIER - not the style' : '') + (r.note ? '; ' + r.note : ''); };
const vars = { IMAGE_COUNT: String(urls.length), REFERENCE_NOTES: refs.map(noteLine).join('\n') };
const text = String(tpl.body).replace(/\{\{\s*([A-Z_]+)\s*\}\}/g, (m, k) => (k in vars ? vars[k] : m));
const content = [{ type: 'text', text }].concat(urls.map((url) => ({ type: 'image_url', image_url: { url } })));
return { json: { body: { messages: [{ role: 'user', content }], response_format: { type: 'json_object' } }, template_version: tpl.version, reference_count: urls.length, reference_notes: vars.REFERENCE_NOTES } };

// Pass A never fails the run - any problem yields sheets = null and the profiler works from the images alone
const j = $input.first().json || {};
const expected = $('List Library').all().map((i) => i.json).filter((r) => r && r.path).length;
let sheets = null, note = '', sheetVersion = null;
try { sheetVersion = $('Build Sheet Request').first().json.template_version || null; } catch (e) { sheetVersion = null; }
try {
  const content = (j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content) || '';
  const why = (typeof j.error === 'object' && j.error) ? (j.error.message || j.error.description) : (j.error || j.msg);
  if (!content) throw new Error(why ? String(why).replace(/:/g, ' -').slice(0, 160) : 'no reply from the vision model');
  const cleaned = String(content).replace(/```json|```/g, '').trim();
  const m = cleaned.match(/[\[{][\s\S]*[\]}]/);
  const parsed = JSON.parse(m ? m[0] : cleaned);
  const arr = Array.isArray(parsed) ? parsed : (parsed && parsed.sheets);
  if (!Array.isArray(arr)) throw new Error('reply has no sheets array');
  if (arr.length !== expected) throw new Error('sheet count mismatch - expected ' + expected + ' got ' + arr.length);
  sheets = arr.map((s, i) => Object.assign({}, (s && typeof s === 'object') ? s : {}, { image: i + 1 }));
} catch (e) { sheets = null; note = String(e.message || e).slice(0, 200); }
return { json: { sheets, sheet_note: note, sheet_template_version: sheetVersion } };

const j = $json || {};
if (!Array.isArray(j.errors) || !j.card || typeof j.card !== 'object') throw new Error('style-card-check returned no errors array - ' + JSON.stringify(j).slice(0, 200).replace(/:/g, '='));
const model = ($('Get Settings').first().json.openrouter_models || {}).text || 'anthropic/claude-sonnet-4.6';
const text = 'Return the full JSON with ONLY these violations fixed, changing nothing else, keeping every other value byte-identical: ' + j.errors.join('; ') + '\n' + JSON.stringify(j.card);
return { json: { body: { model, max_tokens: 8000, messages: [{ role: 'user', content: text }] }, errors: j.errors, card: j.card } };

const req = $('Build Repair Request').first().json;
const was = 'Style Card failed validation (' + (req.errors || []).join('; ').replace(/:/g, ' -') + ')';
if (!$json.choices) { const e = (typeof $json.error === 'object' && $json.error) || {}; let why = String($json.msg || e.message || (typeof $json.error === 'string' ? $json.error : '') || 'no reply'); const code = $json.code || e.status || e.httpCode || e.code || '?'; if (String(code) === '401' || String(code) === '403') why = 'OpenRouter API key missing or invalid - add it in n8n WF-0 Studio Config (OpenRouter Config node)'; throw new Error(was + ' and the repair call failed (OpenRouter error ' + code + ' - ' + why.replace(/:/g, ' -').slice(0, 160) + ')'); }
const content = ($json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '';
const cleaned = String(content).replace(/```json|```/g, '').trim();
const m = cleaned.match(/\{[\s\S]*\}/);
let card;
try { card = JSON.parse(m ? m[0] : cleaned); } catch (e) { throw new Error(was + ' and the repair reply was not JSON - ' + cleaned.slice(0, 160).replace(/:/g, '=')); }
if (!card || typeof card !== 'object' || Array.isArray(card)) throw new Error(was + ' and the repair reply was not an object');
// the studio-set keys never come from the model
const src = $('Parse Style Card').first().json;
card.rules = Object.assign({}, card.rules || {}, (src.style_card || {}).rules || {});
card.reference_ids = (src.style_card || {}).reference_ids || [];
card.source = 'library';
return { json: { style_card: card, template_version: src.template_version, template_versions: src.template_versions, reference_count: src.reference_count, repaired_errors: req.errors } };

const j = $json || {};
const cfg = $('Config').first().json;
const text = (v) => (v === undefined || v === null || v === '' ? '' : (typeof v === 'object' ? String(v.message || v.description || JSON.stringify(v)) : String(v)));
const validation = Array.isArray(j.errors) && j.errors.length ? 'Style Card still fails validation after one repair - ' + j.errors.join(' - ').replace(/:/g, ' -') : '';
const message = (validation || text(j.error) || text(j.message) || text(j.msg) || text(j.detail) || text(j.hint) || 'style draft failed').slice(0, 500);
// keep whatever the run produced so the failure can be judged and a re-run costs only what is missing (sheets survive a Pass B failure)
const out = (n) => { try { return ($(n).isExecuted && $(n).first().json) || {}; } catch (e) { return {}; } };
const chk = $('Check Repaired Card').isExecuted ? out('Check Repaired Card') : out('Check Style Card');
const card = chk.card || out('Parse Repair').style_card || out('Parse Style Card').style_card || null;
const raw = { sheets: out('Parse Sheets').sheets || null, card, validation: Array.isArray(chk.errors) ? { errors: chk.errors, warnings: chk.warnings || [], fixes: chk.fixes || [], agreement: chk.agreement || {} } : null, template_versions: out('Parse Style Card').template_versions || null };
return { json: { message, requestId: cfg.requestId, clientId: cfg.clientId, raw } };

const cfg = $('Load Config').first().json;
const tpl = $('Get Templates').all().map((i) => i.json).find((t) => t && t.slug === 'style_profiler');
if (!tpl || !tpl.body) throw new Error('no active style_profiler template in prompt_templates');
const client = $('Get Client').first().json || {};
const refs = $('List Library').all().map((i) => i.json);
const urls = $('Sign Library Ref').all().map((i) => cfg.sbUrl + '/storage/v1' + String(i.json.signedURL || '')).filter((u) => /token=/.test(u));
if (!urls.length) throw new Error('no signed library URLs');
if (urls.length !== refs.length) throw new Error('Could not sign ' + (refs.length - urls.length) + ' of ' + refs.length + ' library images - nothing was changed, try again');
// image numbers in the evidence refer to this order (newest first, ties by id) - recorded so the wizard can show the right thumbnails
const noteLine = (r, i) => { const m = (r.meta && typeof r.meta === 'object') ? r.meta : {}; return 'Image ' + (i + 1) + ': ' + (m.kind || 'design') + (m.garment ? ' on a ' + m.garment + ' garment' : '') + (Array.isArray(m.best_for) && m.best_for.length ? '; best example of ' + m.best_for.join(', ') : '') + (m.outlier ? '; OUTLIER - not the style' : '') + (r.note ? '; ' + r.note : ''); };
const sheets = ($input.first().json || {}).sheets;
const sb = (client.style_brief && typeof client.style_brief === 'object') ? client.style_brief : {};
const list = (v) => (Array.isArray(v) ? v.map((x) => String(x || '').trim()).filter(Boolean) : String(v || '').split(/\n|;/).map((x) => x.trim()).filter(Boolean));
const rules = { palette_mode: sb.palette_mode === 'flexible' ? 'flexible' : 'strict', text_case: ['upper', 'title'].includes(sb.text_case) ? sb.text_case : 'as_typed', lock_typography: sb.lock_typography !== false, lock_composition: sb.lock_composition !== false };
const briefVars = { NICHE: [sb.niche, sb.audience].filter(Boolean).join(' / ') || 'not given', SUBJECTS: list(sb.subjects).join('; ') || 'not given', BRAND_TEXT: list(sb.brand_text).join('; ') || 'none given', TYPOGRAPHY_NOTE: String(sb.typography_note || '').trim() || 'none', MUST_HAVE: list(sb.must_have).join('; ') || 'none given', AVOID: list(sb.avoid).join('; ') || 'none given', PALETTE_MODE: rules.palette_mode, TEXT_CASE: rules.text_case, LOCK_TYPOGRAPHY: rules.lock_typography ? 'locked' : 'a guide', LOCK_COMPOSITION: rules.lock_composition ? 'locked' : 'a guide' };
const vars = Object.assign({ CLIENT_NAME: client.name || '', CLIENT_NOTES: client.notes || 'none', GARMENT_COLORS: list(client.garment_colors).join(', ') || 'not given', IMAGE_COUNT: String(urls.length), REFERENCE_NOTES: refs.map(noteLine).join('\n'), SHEETS_JSON: Array.isArray(sheets) ? JSON.stringify(sheets) : 'not available - describe from the images' }, briefVars);
const text = String(tpl.body).replace(/\{\{\s*([A-Z_]+)\s*\}\}/g, (m, k) => (k in vars ? vars[k] : m));
const content = [{ type: 'text', text }].concat(urls.map((url) => ({ type: 'image_url', image_url: { url } })));
return { json: { body: { messages: [{ role: 'user', content }], response_format: { type: 'json_object' } }, template_version: tpl.version, reference_count: urls.length, reference_ids: refs.map((r) => String(r.id)), rules, brief: sb } };

if (!$json.choices) { const e = (typeof $json.error === 'object' && $json.error) || {}; const via = $('OpenRouter Profile Style').isExecuted ? ($('Profile Style').isExecuted ? 'Kie and OpenRouter' : 'OpenRouter') : 'Kie'; let why = String($json.msg || e.message || (typeof $json.error === 'string' ? $json.error : '') || 'no reply'); const inner = why.match(/message\\?":\\?"([^"\\]+)/); if (inner) why = inner[1]; const code = $json.code || e.status || e.httpCode || e.code || '?'; if (via !== 'Kie' && (String(code) === '401' || String(code) === '403')) why = 'OpenRouter API key missing or invalid - add it in n8n WF-0 Studio Config (OpenRouter Config node)'; throw new Error('Vision service unavailable (' + via + ' error ' + code + ' - ' + why.replace(/:/g, ' -').slice(0, 160) + '). Nothing was changed; try again in a few minutes.'); }
const content = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '';
const cleaned = String(content).replace(/```json|```/g, '').trim();
const m = cleaned.match(/\{[\s\S]*\}/);
let card;
try { card = JSON.parse(m ? m[0] : cleaned); } catch (e) { throw new Error('style profiler returned no JSON - reply was ' + cleaned.slice(0, 200).replace(/:/g, '=')); }
if (!card || typeof card !== 'object' || Array.isArray(card)) throw new Error('style profiler returned no object');
// JSON extraction only - the shape is judged by the style-card-check Edge Function next; the studio-set keys travel with the card
const req = $('Build Style Request').first().json;
card.rules = Object.assign({}, card.rules || {}, req.rules || {});
card.reference_ids = req.reference_ids || [];
card.source = 'library';
const tpls = $('Get Templates').all().map((i) => i.json);
const ver = (slug) => { const t = tpls.find((x) => x && x.slug === slug); return t ? t.version : null; };
const sheetsUsed = Array.isArray(($('Parse Sheets').first().json || {}).sheets);
return { json: { style_card: card, template_version: req.template_version, template_versions: { sheet: sheetsUsed ? ver('style_sheet') : null, profiler: ver('style_profiler') }, reference_count: req.reference_count } };

const j = $json;
const first = Array.isArray(j) ? j[0] : j;
let id = '';
if (typeof first === 'string') id = first;
else if (first && typeof first === 'object') id = first.id || first.style_card_id || first.data || first.new_style_card_version || '';
if (id && typeof id === 'object') id = id.id || '';
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(id))) throw new Error('new_style_card_version returned no id - ' + JSON.stringify(j).slice(0, 200).replace(/:/g, '='));
// audit trail for style_draft_requests.raw: what the profiler saw and how the validator judged the stored card
const chk = $('Check Repaired Card').isExecuted ? $('Check Repaired Card').first().json : $('Check Style Card').first().json;
const raw = { sheets: $('Parse Sheets').first().json.sheets || null, card: chk.card || null, validation: { errors: chk.errors || [], warnings: chk.warnings || [], fixes: chk.fixes || [], agreement: chk.agreement || {} }, template_versions: $('Parse Style Card').first().json.template_versions || null, repaired: Boolean($('Check Repaired Card').isExecuted) };
return { json: { style_card_id: String(id), version: (first && typeof first === 'object' && first.version) || null, raw } };
